new:
if !controller_blockers(
    world,
    ControllerBlockerQuery {
        center: snap,
        half_extents,
        mask: self.collision_mask,
        ignore_entity,
        drop_through_seconds: self.drop_through_seconds,
        start: position,
        delta: Vec2::new(0.0, -self.ground_snap),
    },
)
.is_empty()
